 await writeFile(join(dir,'session.mjs'),`import {appendFile} from 'node:fs/promises';export async function withSyntheticStackSession(o,fn){let active=false;return fn({output:'.',checkpoint:async()=>{},activate:()=>{active=true},capabilities:{nativeEmailAuthentication:{get requiresReconciliation(){return active},get notificationState(){return active?'active':'contained'},finishCollection:async()=>{await appendFile('effects','contained\\n')}}}})}`);
 await writeFile(join(dir,'fail.mjs'),`import {appendFile} from 'node:fs/promises';export async function run(){await appendFile('effects','fail\\n');throw Error('independent failure')}`);
 await writeFile(join(dir,'activate.mjs'),`import {appendFile} from 'node:fs/promises';export async function run(s){s.activate();await appendFile('effects','activate\\n');return {}}`);
 for(const path of['session.mjs','fail.mjs','activate.mjs']){const sha256=createHash('sha256').update(await readFile(join(dir,path))).digest('hex'),row=m.files.find(x=>x.path===path);if(row)row.sha256=sha256;else m.files.push({path,sha256});}
 m.scenarios.unshift({id:'independent',module:'fail.mjs',export:'run',testIds:[],supporting:true,dependencies:[],produces:'independent'},{id:'activate',module:'activate.mjs',export:'run',testIds:[],supporting:true,dependencies:[],produces:'activated'},{id:'dependent',module:'one.mjs',export:'run',testIds:[],supporting:true,dependencies:[],requires:['independent'],produces:'dependent'});
