test('nested aggregate summaries preserve hashed leaves and only frozen source frames',()=>{
 const file=resolve('scripts/release/simulation-native-agent.mjs'),checked=new Map([['scripts/release/simulation-native-agent.mjs',file]]),leaf=new Error('SECRET password OTP token');
 leaf.stack=`Error: SECRET password OTP token\n    at ${new URL('file:///'+file.replaceAll('\\','/')).href}:24:7`;
 const summary=privateErrorSummary(new AggregateError([new AggregateError([leaf],'SECRET inner')],'SECRET outer'),checked),actual=summary.errors[0].errors[0];
 assert.equal(actual.messageSha256,createHash('sha256').update(leaf.message).digest('hex'));
 assert.deepEqual(actual.sourceLocation,{path:'scripts/release/simulation-native-agent.mjs',line:24,column:7});
 assert.doesNotMatch(JSON.stringify(summary),/SECRET|password|OTP|token|file:\/\//u);
});
test('aggregate summaries bound cycles depth and total count without exposing messages',()=>{
 const cycle=new AggregateError([],'SECRET cycle');cycle.errors.push(cycle);
 assert.equal(privateErrorSummary(cycle,new Map()).errors[0].errorsTruncated,'cycle');
 let nested=new Error('SECRET leaf');for(let i=0;i<8;i++)nested=new AggregateError([nested],'SECRET depth');
 const depth=privateErrorSummary(nested,new Map());let current=depth;for(let i=0;i<4;i++)current=current.errors[0];assert.equal(current.errorsTruncated,'depth');
 const broad=privateErrorSummary(new AggregateError(Array.from({length:100},()=>new Error('SECRET value')),'SECRET root'),new Map());
 assert.equal(broad.errors.length,31);assert.equal(broad.errorsTruncated,'count');
 assert.doesNotMatch(JSON.stringify([depth,broad,privateErrorSummary(cycle,new Map())]),/SECRET/u);
});


test('selected contract reads immutable requirement proofs only from its evidence snapshot',async()=>{
  for(const tampered of [false,true])await full(async({dir,m,catalog,run})=>{
    m.scope='selected-vertical';
    const matrix=await readFile(join(dir,'matrix.json')),assertion=Buffer.from('assert requirement r1'),sha=bytes=>createHash('sha256').update(bytes).digest('hex');
    const matrixPath='output/requirement-matrix.json',assertionPath='output/requirement-assertion.mjs';
    await writeFile(join(m.evidenceSnapshot.root,matrixPath),matrix);
    await writeFile(join(m.evidenceSnapshot.root,assertionPath),tampered?'changed':assertion);
    const item=catalog.journeys[0].useCases[0].tests[0],before=[...item.requirementIds];
    item.requirementIds=[...before,'r1'];
    catalog.reviews.push({kind:'requirement-mapping-correction',candidateId:'app',reviewer:'independent',reason:'Preserve reviewed assertion mapping',source:'source review',recordedAt:'2026-09-16T00:00:00Z',matrix:{path:matrixPath,sha256:sha(matrix)},assertionEvidence:[{path:assertionPath,sha256:sha(assertion),capturedAt:'2026-09-15T00:00:00Z',originalSha:m.application.sha,originalTree:m.application.tree}],changes:[{testId:item.id,journeyId:'journey/usecase',before:{requirementIds:before},after:{requirementIds:item.requirementIds}}]});
    await writeFile(join(dir,'catalog.json'),JSON.stringify(catalog));
    m.files.find(f=>f.path==='catalog.json').sha256=sha(await readFile(join(dir,'catalog.json')));
    await assert.rejects(access(join(dir,matrixPath)));
    const result=await run();
    if(tampered){assert.notEqual(result.status,0);await assert.rejects(access(join(dir,'effects')));await assert.rejects(access(join(dir,'manifest-'+m.namespace)));}
    else{assert.match(await readFile(join(dir,'effects'),'utf8'),/^session\n/);await access(join(dir,'stage-outcomes.json'));}
  });
});
